namespace BlueHead.Desktop;

internal static partial class Program
{
    private static void CodecBitrateChecks(Dictionary<string, bool> checks)
    {
        var defaults = new Dictionary<string, CodecParameters>();
        checks["codec_bitrate_labels_cover_all_classic_codecs_without_changing_auto"] = CodecPolicyWindow.Codecs.All(item => CodecBitrateLimits.Label(item.Code, defaults).StartsWith(item.Name + " · 约") && CodecBitrateLimits.Label(item.Code, defaults).Contains("kb/s")) && CodecBitrateLimits.Label("auto", defaults) == "自动 · 优先高清";
        checks["aptx_common_bitrate_tracks_sample_rate_and_rounds_for_readability"] = CodecBitrateLimits.CommonRangeKbps("aptx", new() { rate = 44100 }) == (353, 353) && CodecBitrateLimits.CommonRangeKbps("aptx", new() { rate = 48000 }) == (384, 384) && CodecBitrateLimits.CommonRangeKbps("aptx_hd", new() { rate = 44100 }) == (529, 529) && CodecBitrateLimits.CommonRangeKbps("aptx_hd") == (529, 576);
        checks["ldac_common_ranges_follow_sample_rate_family_and_source_quality_modes"] = new[] { 44100, 88200 }.All(rate => CodecBitrateLimits.CommonRangeKbps("ldac", new() { rate = rate }) == (303, 910)) && new[] { 48000, 96000 }.All(rate => CodecBitrateLimits.CommonRangeKbps("ldac", new() { rate = rate }) == (330, 990)) && CodecBitrateLimits.CommonRangeKbps("ldac") == (303, 990);
        checks["aac_common_reference_respects_explicit_and_quality_limits"] = CodecBitrateLimits.CommonRangeKbps("aac", new() { bitrate = 320000, quality = "balanced" }) == (256, 256) && CodecBitrateLimits.CommonRangeKbps("aac", new() { bitrate = 128000, quality = "balanced" }) == (128, 128) && CodecBitrateLimits.CommonRangeKbps("aac", new() { quality = "bandwidth" }) == (192, 192) && CodecBitrateLimits.CommonRangeKbps("aac") == (256, 320);
        checks["aac_legacy_alias_is_not_lost_or_forced_over_explicit_settings"] = CodecBitrateLimits.CommonRangeKbps("aac_192") == (192, 192) && CodecBitrateLimits.CommonRangeKbps("aac_192", new() { bitrate = 320000 }) == (256, 320) && CodecBitrateLimits.CommonRangeKbps("aac_192", new() { quality = "high" }) == (256, 320);
        checks["sbc_common_profile_tracks_quality_and_avoids_protocol_maximum"] = CodecBitrateLimits.CommonRangeKbps("sbc") == (328, 357) && CodecBitrateLimits.CommonRangeKbps("sbc", new() { quality = "balanced" }) == (256, 279) && CodecBitrateLimits.CommonRangeKbps("sbc", new() { quality = "bandwidth" }) == (212, 231) && CodecBitrateLimits.CommonRangeKbps("sbc", new() { rate = 44100, quality = "bandwidth" }) == (212, 212) && CodecBitrateLimits.CommonRangeKbps("sbc", new() { rate = 48000 }) == (357, 357) && !CodecBitrateLimits.Label("sbc", defaults).Contains("512");
        checks["lhdc_reference_does_not_fabricate_a_source_quality_choice"] = new[] { 44100, 48000, 96000, 192000 }.All(rate => new[] { 16, 24 }.All(depth => CodecBitrateLimits.CommonRangeKbps("lhdc5", new() { rate = rate, depth = depth }) == (400, 1000))) && CodecBitrateLimits.Description("lhdc5", defaults).Contains("由发送设备选择") && CodecBitrateLimits.Description("lhdc5", defaults).Contains("码率还可能更低");
        defaults["aac"] = new() { bitrate = 128000 };
        defaults["ldac"] = new() { rate = 88200 };
        checks["codec_bitrate_labels_read_live_saved_parameters_independently"] = CodecBitrateLimits.Label("aac", defaults) == "AAC · 约128 kb/s" && CodecBitrateLimits.Label("ldac", defaults) == "LDAC · 约303–910 kb/s" && CodecBitrateLimits.Label("aptx_hd", defaults) == "aptX HD · 约529–576 kb/s";
        checks["common_bitrate_options_omit_theoretical_maximum_and_precision_noise"] = CodecPolicyWindow.Codecs.All(item => !CodecBitrateLimits.Label(item.Code, defaults).Contains('≤') && !CodecBitrateLimits.Label(item.Code, defaults).Contains('*') && !CodecBitrateLimits.Label(item.Code, defaults).Contains(".6") && !CodecBitrateLimits.Description(item.Code, defaults).Contains("理论"));
        checks["codec_bitrate_help_distinguishes_common_reference_from_live_measurement"] = CodecPolicyWindow.Codecs.All(item => CodecBitrateLimits.Description(item.Code, defaults).Contains("不是当前连接的实测值") && CodecBitrateLimits.Description(item.Code, defaults).Contains("实际码率请看设备卡片") && CodecBitrateLimits.Description(item.Code, defaults).Contains("不同编码的码率不能直接用来比较音质"));
    }
}
